#!/usr/bin/env bash
# Doc développeur : la partie « L’éditeur de texte riche », en deux chapitres.
# Prérequis : apply-docs-recadrage.sh.
# Usage (racine du repo) : bash apply-docs-editeur.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"apps/web/content/docs/dev/editeur/un-modele-adopte-puis-taille.mdx" 2>/dev/null | grep -qF "Un modèle adopté, puis taillé"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "Le composant de recadrage, en deux chapitres" "apps/web/content/docs/dev/index.mdx" 2>/dev/null || { echo "❌ lancer d'abord apply-docs-recadrage.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/contenu/reglages-du-site.mdx" "apps/web/content/docs/dev/index.mdx" "apps/web/src/features/docs/lib/docs.navigation.ts")
CREATED=("apps/web/content/docs/dev/editeur/un-modele-adopte-puis-taille.mdx" "apps/web/content/docs/dev/editeur/une-image-de-la-bibliotheque.mdx")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; rmdir -p "apps/web/content/docs/dev/editeur" 2>/dev/null || true; echo "  ↩ fichiers restaurés"; }
if grep -qF "Un modèle adopté, puis taillé" "apps/web/content/docs/dev/editeur/un-modele-adopte-puis-taille.mdx" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
if ! git diff --quiet HEAD -- "${MODIFIED[@]}" 2>/dev/null; then echo "❌ modifications non commitées dans des fichiers que ce script modifie (rien n'a été touché) :"; git diff --name-only HEAD -- "${MODIFIED[@]}" | head -5; exit 1; fi
trap 'restore' ERR

mkdir -p "apps/web/content/docs/dev/editeur"
